import { expect, test } from '@playwright/test';

test('has title', async ({ page }) => {
  await page.goto('/');

  // Expect a title "to contain" a substring.
  await expect(page).toHaveTitle(/Formulardesigner/);
});

test('Einfaches Textfeld can be dragged', async ({ page }) => {
  await page.goto('/');
  await page.locator('#form-sections-tabpanel-0').getByRole('button', { name: 'Einfache Feldgruppe' }).click();
  await page.getByLabel('ID', { exact: true }).fill('gruppe1');
  await expect(page.locator('#s0-c0')).toContainText('Einfache Feldgruppe');
  await page.getByRole('button', { name: 'Einzeiliges Textfeld' }).dragTo(page.locator('#s0-c0'));
  await expect(page.locator('#s0-c0-r0-f0')).toBeVisible();
});

