import { expect, Page, test } from '@playwright/test';
import { loadFixture } from './utils/common';
import { DisplayConditionsFixture } from './fixtures/display-conditions';

async function loadFixtureAndOpenDisplayConditionsTab({
  page,
  fixture,
}: {
  page: Page;
  fixture: Record<string, unknown>;
}) {
  await loadFixture({ page, fixture });
  await page.locator('#s0-c0-r0-f0').click();
  await page.waitForTimeout(300);
  await page.getByRole('tab', { name: 'Sichtbarkeit' }).click();
  await page.waitForTimeout(300);
}

async function loadFixtureAndOpenDisplayConditionsDialog({
  page,
  fixture,
}: {
  page: Page;
  fixture: Record<string, unknown>;
}) {
  await loadFixtureAndOpenDisplayConditionsTab({ page, fixture });
  await page.getByRole('button', { name: 'Bearbeiten' }).click();
}

test.describe('Sichtbarkeitsbedingungen', () => {
  test(`STRING hat Tab "Sichtbarkeit"`, async ({ page }) => {
    await loadFixture({ page, fixture: DisplayConditionsFixture });
    await page.locator('#s0-c0-r0-f1').click();
    await expect(page.getByRole('tab', { name: 'Sichtbarkeit' })).toBeVisible();
  });

  test(`DOWNLOAD hat keinen Tab "Sichtbarkeit"`, async ({ page }) => {
    await loadFixture({ page, fixture: DisplayConditionsFixture });
    await page.locator('#s0-c0-r0-f2').click();
    await expect(page.getByRole('tab', { name: 'Sichtbarkeit' })).not.toBeVisible();
